After installing (npm install @reduxjs/toolkit react-redux), defining a 'slice' — a self-contained piece of state with its own actions and reducer logic:

import { createSlice, configureStore } from '@reduxjs/toolkit';

interface CartItem {
  id: number;
  name: string;
  quantity: number;
}

const cartSlice = createSlice({
  name: 'cart',
  initialState: { items: [] as CartItem[] },
  reducers: {
    addItem: (state, action: { payload: CartItem }) => {
      state.items.push(action.payload); // Redux Toolkit allows this
                                           // direct-looking mutation -
                                           // see internalWorking below
    },
    removeItem: (state, action: { payload: number }) => {
      state.items = state.items.filter((item) => item.id !== action.payload);
    }
  }
});

export const { addItem, removeItem } = cartSlice.actions;

const store = configureStore({
  reducer: { cart: cartSlice.reducer }
});

export default store;

