import { useSelector, useDispatch, Provider } from 'react-redux';
import store, { addItem, removeItem } from './store';

interface RootState {
  cart: { items: CartItem[] };
}

function CartSummary() {
  // useSelector reads a specific slice of state, re-rendering this
  // component ONLY when that specific selected value actually changes
  const items = useSelector((state: RootState) => state.cart.items);
  const dispatch = useDispatch();

  return (
    <ul>
      {items.map((item) => (
        <li key={item.id}>
          {item.name} x{item.quantity}
          <button onClick={() => dispatch(removeItem(item.id))}>Remove</button>
        </li>
      ))}
    </ul>
  );
}

function ProductCard({ product }: { product: CartItem }) {
  const dispatch = useDispatch();
  return (
    <button onClick={() => dispatch(addItem(product))}>
      Add {product.name} to cart
    </button>
  );
}

function App() {
  return (
    <Provider store={store}>
      <ProductCard product={{ id: 1, name: 'Widget', quantity: 1 }} />
      <CartSummary />
    </Provider>
  );
}

