import { createSlice, configureStore } from '@reduxjs/toolkit';
import { useSelector, useDispatch, Provider } from 'react-redux';

interface Notification {
  id: number;
  message: string;
}

const notificationsSlice = createSlice({
  name: 'notifications',
  initialState: { items: [] as Notification[] },
  reducers: {
    addNotification: (state, action: { payload: string }) => {
      state.items.push({ id: Date.now(), message: action.payload });
    },
    removeNotification: (state, action: { payload: number }) => {
      state.items = state.items.filter((n) => n.id !== action.payload);
    },
    clearAll: (state) => {
      state.items = [];
    }
  }
});

export const { addNotification, removeNotification, clearAll } = notificationsSlice.actions;

const store = configureStore({ reducer: { notifications: notificationsSlice.reducer } });

interface RootState {
  notifications: { items: Notification[] };
}

function NotificationBell() {
  const items = useSelector((state: RootState) => state.notifications.items);
  return <span>Notifications: {items.length}</span>;
}

function NotificationTrigger() {
  const dispatch = useDispatch();
  return <button onClick={() => dispatch(addNotification('New message!'))}>Trigger</button>;
}

function App() {
  return (
    <Provider store={store}>
      <NotificationBell />
      <NotificationTrigger />
    </Provider>
  );
}

