After installing (npm install zustand), defining a store as a custom hook:

import { create } from 'zustand';

interface CartState {
  items: CartItem[];
  addItem: (item: CartItem) => void;
  removeItem: (id: number) => void;
}

const useCartStore = create<CartState>((set) => ({
  items: [],
  addItem: (item) => set((state) => ({ items: [...state.items, item] })),
  removeItem: (id) => set((state) => ({
    items: state.items.filter((i) => i.id !== id)
  }))
}));

Using it directly in any component, with no Provider needed at all:

function CartSummary() {
  const items = useCartStore((state) => state.items); // selects just
                                                          // this slice,
                                                          // re-rendering
                                                          // only when it changes
  return <p>{items.length} items in cart</p>;
}

function ProductCard({ product }: { product: CartItem }) {
  const addItem = useCartStore((state) => state.addItem);
  return <button onClick={() => addItem(product)}>Add to cart</button>;
}

