import { create } from 'zustand';

interface Notification {
  id: number;
  message: string;
}

interface NotificationState {
  items: Notification[];
  addNotification: (message: string) => void;
  removeNotification: (id: number) => void;
  clearAll: () => void;
}

const useNotificationStore = create<NotificationState>((set) => ({
  items: [],
  addNotification: (message) =>
    set((state) => ({ items: [...state.items, { id: Date.now(), message }] })),
  removeNotification: (id) =>
    set((state) => ({ items: state.items.filter((n) => n.id !== id) })),
  clearAll: () => set({ items: [] })
}));

function NotificationBell() {
  const items = useNotificationStore((state) => state.items);
  return <span>Notifications: {items.length}</span>;
}

function NotificationTrigger() {
  const addNotification = useNotificationStore((state) => state.addNotification);
  return <button onClick={() => addNotification('New message!')}>Trigger</button>;
}

// Notice: NO Provider, NO action constants, NO separate reducer
// function, NO configureStore call - just one create() call, and
// both components import and call the resulting hook directly

