After installing (npm install @tanstack/react-query), wrapping the application in a QueryClientProvider (directly analogous to lesson 2's Redux Provider):

import { QueryClient, QueryClientProvider, useQuery, useMutation, useQueryClient } from '@tanstack/react-query';

const queryClient = new QueryClient();

function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <TaskList />
    </QueryClientProvider>
  );
}

Fetching with useQuery — directly replacing Module 6, lesson 5's entire useState/useEffect pattern:

function TaskList() {
  const { data: tasks, isLoading, error } = useQuery({
    queryKey: ['tasks'],
    queryFn: () => fetch('/api/tasks').then((res) => res.json())
  });

  if (isLoading) return <p>Loading...</p>;
  if (error) return <p>Error loading tasks</p>;
  return <ul>{tasks.map((t: Task) => <li key={t.id}>{t.title}</li>)}</ul>;
}

Mutating with useMutation, and invalidating the cached query afterward:

function AddTaskButton() {
  const queryClient = useQueryClient();
  const mutation = useMutation({
    mutationFn: (title: string) =>
      fetch('/api/tasks', { method: 'POST', body: JSON.stringify({ title }) }),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['tasks'] }); // triggers
        // an automatic refetch, keeping TaskList's data genuinely fresh
    }
  });

  return <button onClick={() => mutation.mutate('New Task')}>Add Task</button>;
}

