// 1. SERVER STATE (lesson 4) - tasks genuinely live on the backend
function useTasksQuery() {
  return useQuery<Task[]>({
    queryKey: ['tasks'],
    queryFn: () => fetch('/api/tasks').then((res) => res.json())
  });
}

// 2. LOCAL STATE (Module 6) - a single TaskCard's own expand/collapse
// state, needed only within that one component, nowhere else
function TaskCard({ task }: { task: Task }) {
  const [expanded, setExpanded] = useState(false);
  return (
    <div onClick={() => setExpanded(!expanded)}>
      <h3>{task.title}</h3>
      {expanded && <p>{task.description}</p>}
    </div>
  );
}

// 3. CONTEXT (Module 14) - authentication status, narrowly-scoped,
// infrequently-changing, needed broadly across the app
function TaskBoardHeader() {
  const { user, logout } = useAuth(); // Module 10/14's AuthContext pattern
  return <button onClick={logout}>Log out, {user?.name}</button>;
}

// 4. CLIENT STATE LIBRARY (lesson 3, Zustand here) - the currently
// active filter/sort settings, needed across several unrelated
// components (a filter bar, the task list, a results counter),
// changing frequently as a user adjusts filters
const useFilterStore = create<FilterState>((set) => ({
  status: 'all',
  setStatus: (status) => set({ status })
}));

function TaskBoard() {
  const { data: tasks } = useTasksQuery();           // (1) server state
  const status = useFilterStore((s) => s.status);     // (4) client state library

  const filteredTasks = tasks?.filter((t) =>
    status === 'all' ? true : t.status === status
  );

  return (
    <div>
      <TaskBoardHeader />                              {/* (3) Context */}
      {filteredTasks?.map((task) => <TaskCard key={task.id} task={task} />)}
      {/* TaskCard manages its own (2) local state internally */}
    </div>
  );
}

